            argv=(
                *settings.command,
                "--ask-for-approval",
                "never",
                "exec",
                "--json",
                "--sandbox",
                "workspace-write",
                "-C",
                str(request.root),
                *(("-m", model) if model is not None else ()),
                *effort_arguments,
                "--",
                request.prompt,
